<script setup lang="ts">
import {computed,onMounted,onUnmounted,ref} from 'vue'
import {api,apiBaseUrl} from '../lib/api'
import {asset,assets} from '../lib/assets'
const props=defineProps<{token:string}>()
type Media={id:string;url:string;kind:string;src?:string}
type Moment={id:string;userId:string;content:string;visibility:string;createdAt:string;attachments:Media[]}
type Card={id:string;url:string;type:string;visibility:string;isPrimary:boolean;src?:string}
const cards=ref<Card[]>([]),posts=ref<Moment[]>([]),owner=ref(''),screen=ref(''),sheet=ref(''),error=ref(''),notice=ref(''),busy=ref(false),loading=ref(false),more=ref(false)
const card=ref<Card>(),moment=ref<Moment>(),type=ref('portrait'),category=ref('All'),text=ref(''),audience=ref('everyone'),attachments=ref<Media[]>([]),picker=ref<HTMLInputElement>(),cardPicker=ref<HTMLInputElement>()
const types=['portrait','physique','outfit','life'],visibility=[['everyone','Everyone'],['friends','Friends'],['only_me','Only me']]
const stickers=assets.filter(a=>a.category==='06-stickers').slice(0,24)
const urls:string[]=[]
const draftKey=computed(()=>`maugo-d5-draft-${owner.value}`)
const count=computed(()=>[...text.value].length)
const visible=computed(()=>posts.value.filter(p=>category.value==='All'||p.attachments.some(a=>a.kind===category.value.toLowerCase())))
const state=computed(()=>sheet.value|| (screen.value==='compose'?(attachments.value.length?'moment-photo':text.value?'moment-draft':'moment-empty'):screen.value==='detail'?'moment-detail':screen.value==='moments'?(!posts.value.length?'moments-empty':!visible.value.length?'moments-category-empty':'moments-list'):'image-cards'))
const headers=()=>({Authorization:`Bearer ${props.token}`})
async function request<T>(path:string,method='GET',body?:object){return api<T>(path,{method,headers:{...headers(),...(body?{'Content-Type':'application/json'}:{})},...(body?{body:JSON.stringify(body)}:{})})}
async function hydrate(media:{url:string;src?:string}){const response=await fetch(apiBaseUrl+media.url,{headers:headers()});if(!response.ok)throw Error(`Photo unavailable (${response.status})`);media.src=URL.createObjectURL(await response.blob());urls.push(media.src)}
async function loadCards(){cards.value=(await request<{items:Card[]}>('/users/me/image-cards')).items;await Promise.all(cards.value.map(hydrate))}
async function loadPosts(append=false){const rows=(await request<{items:Moment[]}>(`/posts?userId=${owner.value}&limit=20&offset=${append?posts.value.length:0}`)).items;await Promise.all(rows.flatMap(p=>p.attachments).map(hydrate));posts.value=append?[...posts.value,...rows]:rows;more.value=rows.length===20}
async function act(work:()=>Promise<void>){if(busy.value)return;busy.value=true;error.value='';try{await work()}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function init(){loading.value=true;await act(async()=>{owner.value=(await request<{id:string}>('/profiles/me')).id;await loadCards()});loading.value=false}
onMounted(init)
onUnmounted(()=>urls.forEach(url=>URL.revokeObjectURL(url)))
function label(value:string){return visibility.find(v=>v[0]===value)?.[1]||value}
function openMoments(){screen.value='moments';notice.value='';void act(()=>loadPosts())}
function compose(){const draft=JSON.parse(localStorage.getItem(draftKey.value)||'null');text.value=draft?.text||'';audience.value=draft?.visibility||'everyone';attachments.value=draft?.attachments||[];screen.value='compose';notice.value='';void act(async()=>{await Promise.all(attachments.value.map(hydrate))})}
function back(){if(busy.value)return;if(sheet.value){sheet.value='';return}if(screen.value==='compose'&&(text.value.trim()||attachments.value.length)){sheet.value='moment-leave';return}screen.value=screen.value==='detail'||screen.value==='compose'?'moments':''}
function leave(keep:boolean){if(keep)localStorage.setItem(draftKey.value,JSON.stringify({text:text.value,visibility:audience.value,attachments:attachments.value.map(({id,url,kind})=>({id,url,kind}))}));else localStorage.removeItem(draftKey.value);text.value='';attachments.value=[];sheet.value='';screen.value='moments'}
async function upload(file:File){const allowed=['image/png','image/jpeg','image/webp','video/mp4','video/webm','audio/ogg','audio/wav','audio/mpeg'];if(!allowed.includes(file.type)||file.size>=(file.type.startsWith('video/')?30:10)*1024*1024)throw Error('Use PNG, JPEG, WebP, MP4, WebM, OGG, WAV or MP3 below 10 MB (video below 30 MB).');return api<Media>(`/media/uploads?${new URLSearchParams({purpose:'post',filename:file.name})}`,{method:'POST',headers:{...headers(),'Content-Type':file.type},body:file})}
async function chooseFiles(event:Event){const input=event.target as HTMLInputElement,files=Array.from(input.files||[]);input.value='';if(attachments.value.length+files.length>6){error.value='You can add up to 6 attachments.';return}await act(async()=>{for(const file of files){const media=await upload(file);await hydrate(media);attachments.value.push(media)}})}
async function sticker(name:string){if(attachments.value.length>=6){error.value='You can add up to 6 attachments.';return}await act(async()=>{const blob=await(await fetch(asset(name))).blob(),media=await upload(new File([blob],'sticker.png',{type:'image/png'}));await hydrate(media);attachments.value.push(media);sheet.value=''})}
async function uploadCard(event:Event){const input=event.target as HTMLInputElement,file=input.files?.[0];input.value='';if(!file)return;await act(async()=>{if(!file.type.startsWith('image/'))throw Error('Choose an image.');const media=await upload(file);await request('/users/me/image-cards','POST',{mediaId:media.id,type:type.value});await loadCards();sheet.value='';notice.value='Image card published.'})}
function selectType(value:string){type.value=value;if(sheet.value==='card-change-type'){void patchCard({type:value});return}cardPicker.value!.click()}
async function patchCard(body:object){await act(async()=>{await request(`/users/me/image-cards/${card.value!.id}`,'PATCH',body);await loadCards();sheet.value=''})}
async function publish(){if(count.value>1000||(!text.value.trim()&&!attachments.value.length))return;await act(async()=>{const saved=await request<Moment>('/posts','POST',{content:text.value,mediaIds:attachments.value.map(a=>a.id),visibility:audience.value});localStorage.removeItem(draftKey.value);text.value='';attachments.value=[];await loadPosts();screen.value='moments';notice.value='Moment published.';moment.value=saved})}
async function detail(id:string){await act(async()=>{const row=await request<Moment>(`/posts/${id}`);await Promise.all(row.attachments.map(hydrate));moment.value=row;screen.value='detail'})}
async function remove(){await act(async()=>{if(sheet.value==='card-remove'){await request(`/users/me/image-cards/${card.value!.id}`,'DELETE');await loadCards()}else{await request(`/posts/${moment.value!.id}`,'DELETE');await loadPosts();screen.value='moments'}sheet.value='';notice.value='Deleted.'})}
</script>
<template>
<section class="d5" :data-state="state">
<p v-if="error" role="alert">{{error}} <button :disabled="busy" @click="screen?act(()=>loadPosts()):init()">Retry</button></p>
<p v-if="notice" role="status">{{notice}}</p>
<template v-if="!screen"><div class="section-heading"><h2>Image cards</h2><button id="profile-moments" @click="openMoments">My moments ›</button></div><p v-if="loading">Loading…</p><div class="card-grid"><button v-for="c in cards" :key="c.id" :data-profile-moment="c.id" class="image-card" @click="card=c;sheet='card-options'"><img :src="c.src" alt="Image card"><span>{{c.type}}</span><small>{{c.isPrimary?'Main · ':''}}{{label(c.visibility)}}</small></button><button id="upload-image-card" class="upload-card" :disabled="busy||cards.length>=8||!owner" @click="sheet='card-type'"><b>＋</b><small>Upload a photo</small></button></div><p v-if="!loading&&!cards.length" class="hint">No photos uploaded yet.</p><button id="new-profile-moment" class="compose-link" :disabled="!owner" @click="compose">＋ A little moment</button></template>
<Transition name="d5-page"><section v-if="screen" class="d5-page" @keydown.esc.stop="back"><header><button id="d5-back" aria-label="Back from moments" :disabled="busy" @click="back">‹</button><h1>{{screen==='compose'?'A little moment':screen==='detail'?'Moment':'My moments'}}</h1><button v-if="screen==='moments'" id="new-moment" aria-label="New moment" @click="compose">＋</button><span v-else></span></header><div class="page-body"><p v-if="error" role="alert">{{error}}</p><p v-if="notice" role="status">{{notice}}</p>
<template v-if="screen==='compose'"><textarea id="moment-text" v-model="text" aria-label="Moment text" placeholder="What is on your mind?" :disabled="busy"></textarea><small class="counter" :class="{invalid:count>1000}">{{count}} / 1000</small><div class="media-grid"><div v-for="(a,i) in attachments" :key="a.id"><img v-if="a.kind==='image'" :src="a.src" alt="Attachment"><video v-else-if="a.kind==='video'" :src="a.src" controls></video><audio v-else :src="a.src" controls></audio><button :disabled="busy" :aria-label="`Remove attachment ${i+1}`" @click="attachments.splice(i,1)">×</button></div></div><div class="tools"><button id="moment-photo" :disabled="busy||attachments.length>=6" @click="picker!.click()">▧ Media</button><button id="moment-sticker" :disabled="busy||attachments.length>=6" @click="sheet='moment-stickers'">☺ Stickers</button></div><button id="moment-audience" class="row" :disabled="busy" @click="sheet='moment-visibility'">Who can see this? <small>{{label(audience)}} ›</small></button><p class="hint">Up to 6 attachments. Visibility is enforced when shared.</p><button id="save-moment" class="primary" :disabled="busy||count>1000||(!text.trim()&&!attachments.length)" @click="publish">{{busy?'Publishing…':'Publish moment'}}</button></template>
<template v-else><nav v-if="screen==='moments'" class="categories"><button v-for="c in ['All','Image','Video','Audio']" :key="c" :aria-pressed="category===c" @click="category=c">{{c==='Image'?'Photos':c}}</button></nav><p v-if="screen==='moments'&&!visible.length" class="empty">Keep a little moment here.</p><TransitionGroup name="d5-item"><article v-for="p in screen==='detail'&&moment?[moment]:visible" :key="p.id" class="moment-card"><header><small>{{new Date(p.createdAt).toLocaleDateString()}} · {{label(p.visibility)}}</small><button data-more aria-label="Moment options" @click="moment=p;sheet='moment-options'">•••</button></header><button class="moment-content" @click="screen==='moments'&&detail(p.id)">{{p.content}}</button><div class="media-grid"><template v-for="a in p.attachments" :key="a.id"><img v-if="a.kind==='image'" :src="a.src" alt="Moment photo" @click="screen==='moments'&&detail(p.id)"><video v-else-if="a.kind==='video'" :src="a.src" controls></video><audio v-else :src="a.src" controls></audio></template></div><button v-if="screen==='moments'" class="detail-link" @click="detail(p.id)">View moment ›</button></article></TransitionGroup><button v-if="screen==='moments'&&more" :disabled="busy" class="row" @click="act(()=>loadPosts(true))">Load more</button></template>
</div></section></Transition>
<input ref="picker" type="file" multiple accept="image/png,image/jpeg,image/webp,video/mp4,video/webm,audio/ogg,audio/wav,audio/mpeg" hidden @change="chooseFiles"><input ref="cardPicker" type="file" accept="image/png,image/jpeg,image/webp" hidden @change="uploadCard">
<Transition name="d5-sheet"><div v-if="sheet" class="veil" @click.self="!busy&&(sheet='')"><section role="dialog" aria-modal="true" :aria-label="sheet" class="sheet"><button class="close" aria-label="Close D5 dialog" :disabled="busy" @click="sheet=''">×</button>
<template v-if="sheet==='card-type'||sheet==='card-change-type'"><h2>Photo type</h2><div class="type-options"><button v-for="t in types" :key="t" :data-card-type="t" :disabled="busy" @click="selectType(t)">{{t}}</button></div><button class="row" :disabled="busy" @click="sheet=''">Cancel</button></template>
<template v-else-if="sheet==='card-options'"><h2>Image card</h2><button id="card-view" class="row" @click="sheet='card-preview'">View photo ›</button><button id="card-type" class="row" @click="sheet='card-change-type'">Photo type <small>{{card!.type}} ›</small></button><button id="card-visibility" class="row" @click="sheet='card-visibility'">Visibility <small>{{label(card!.visibility)}} ›</small></button><button class="row" :disabled="busy||card!.isPrimary" @click="patchCard({isPrimary:true})">{{card!.isPrimary?'Main photo':'Set as main photo'}}</button><button id="card-remove" class="row danger" @click="sheet='card-remove'">Remove card</button></template>
<template v-else-if="sheet==='card-preview'"><img class="preview" :src="card!.src" alt="Image card preview"><p>{{card!.type}}</p></template>
<template v-else-if="sheet==='card-visibility'||sheet==='moment-visibility'"><h2>Who can see this?</h2><button v-for="v in visibility" :key="v[0]" class="row" :data-visibility="v[0]" :disabled="busy" @click="sheet==='card-visibility'?patchCard({visibility:v[0]}):(audience=v[0]! ,sheet='')">{{v[1]}} <small>{{(sheet==='card-visibility'?card!.visibility:audience)===v[0]?'✓':''}}</small></button><p>Friends are people with a collected reply.</p></template>
<template v-else-if="sheet==='moment-stickers'"><h2>A little expression</h2><div class="stickers"><button v-for="s in stickers" :key="s.name" :disabled="busy" @click="sticker(s.name)"><img :src="s.url" alt="Add sticker"></button></div></template>
<template v-else-if="sheet==='moment-leave'"><h2>Leave this draft?</h2><p>Keep your draft on this device, or discard it before leaving.</p><button id="keep-moment-draft" class="primary" @click="leave(true)">Keep draft</button><button id="discard-moment-draft" class="row" @click="leave(false)">Discard draft</button><button class="row" @click="sheet=''">Continue editing</button></template>
<template v-else-if="sheet==='moment-options'"><h2>Moment options</h2><button id="moment-visibility" class="row" disabled>Visibility <small>{{label(moment!.visibility)}}</small></button><p>Visibility is set when publishing.</p><button id="delete-moment" class="row danger" @click="sheet='moment-delete'">Delete moment</button></template>
<template v-else><h2>{{sheet==='card-remove'?'Remove this photo?':'Delete this moment?'}}</h2><p>This removes {{sheet==='card-remove'?'the image card from your profile.':'the published moment.'}}</p><button id="d5-confirm-delete" class="primary" :disabled="busy" @click="remove">Delete</button><button class="row" :disabled="busy" @click="sheet=''">Cancel</button></template><p v-if="error" role="alert">{{error}}</p>
</section></div></Transition>
</section>
</template>
<style scoped>
.d5{color:#e4efd9}.d5 button{font:inherit;cursor:pointer;color:inherit;border:0;background:none}.d5 button:disabled{opacity:.4;cursor:default}.d5 h2{font-size:16px;font-weight:500}.section-heading{display:flex;align-items:center;justify-content:space-between}.section-heading button,.hint{font-size:11px;color:#819877}.card-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}.image-card,.upload-card{height:144px;border-radius:12px;overflow:hidden;position:relative;padding:0!important;background:#1b2a20!important}.image-card img{height:100%;width:100%;object-fit:cover}.image-card span{position:absolute;top:8px;left:8px;font-size:9px;background:#080f0b88;padding:3px 5px;border-radius:4px;text-transform:capitalize}.image-card small{position:absolute;bottom:0;left:0;right:0;font-size:9px;padding:10px 5px;background:linear-gradient(transparent,#07100bcc)}.upload-card{border:1px dashed #637e5c66!important;display:flex;flex-direction:column;justify-content:center;align-items:center;gap:18px;color:#819877!important}.upload-card b{font-size:30px;font-weight:400}.upload-card small{font-size:9px}.compose-link{display:block;margin:18px 0;color:#b5fa70!important;font-size:13px!important}.d5-page{position:absolute;inset:0;z-index:35;background:#0d1713;padding-top:48px;display:flex;flex-direction:column}.d5-page>header{display:flex;justify-content:space-between;align-items:center;height:56px;padding:0 24px;flex-shrink:0}.d5-page h1{font-size:19px;font-weight:500}.d5-page>header button{font-size:26px;width:28px;padding:0}.d5-page>header span{width:28px}.page-body{padding:20px 24px 40px;overflow:auto;flex:1}.d5 [role=alert]{color:#edb39f;font-size:12px}.d5 [role=status]{color:#b5fa70;font-size:12px}.d5-page textarea{display:block;resize:none;width:100%;height:180px;background:transparent;color:#e4efd9;border:0;font:inherit;font-size:15px;line-height:1.8;outline-color:#b5fa70}.counter{display:block;text-align:right;color:#819877;font-size:10px}.counter.invalid{color:#edb39f}.tools{display:flex;gap:20px;border-bottom:1px solid #ffffff0a;padding:20px 0}.tools button{font-size:13px;color:#a6bd98}.row{display:block;width:100%;text-align:left;padding:18px 0!important;border-bottom:1px solid #ffffff08!important;font-size:14px!important}.row small{float:right;color:#819877}.d5 .primary{display:block;width:100%;border-radius:24px;background:#b5fa70;color:#183020;min-height:48px;margin-top:20px;font-size:14px}.hint{line-height:1.8}.categories{display:flex;gap:8px;margin-bottom:24px}.categories button{padding:8px 14px;font-size:12px;color:#819877;border-radius:18px}.categories [aria-pressed=true]{background:#293f2b;color:#b5fa70}.empty{text-align:center;margin-top:150px;font-size:13px;color:#819877}.moment-card{padding:18px;background:#1b2a20;border-radius:16px;margin-bottom:16px}.moment-card header{display:flex;justify-content:space-between;align-items:center;color:#819877;font-size:10px}.moment-content{display:block;text-align:left;white-space:pre-wrap;overflow-wrap:anywhere;font-size:14px!important;line-height:1.8;padding:14px 0!important;width:100%}.media-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px;margin-top:14px}.media-grid>*:only-child{grid-column:1/-1}.media-grid>div{position:relative}.media-grid img,.media-grid video{display:block;width:100%;max-height:320px;object-fit:cover;border-radius:12px}.media-grid audio{width:100%;min-width:0}.media-grid>div>button{position:absolute;right:4px;top:4px;background:#0d1713aa;border-radius:50%;width:24px;height:24px}.detail-link{color:#8faa7d!important;font-size:11px!important;margin-top:16px}.veil{position:absolute;inset:0;z-index:45;background:#030805b8;backdrop-filter:blur(5px);display:flex;align-items:flex-end}.sheet{position:relative;width:100%;max-height:85%;overflow:auto;border-radius:26px 26px 0 0;background:#1c2c22;padding:26px 24px 36px;border:1px solid #b8ccb018}.sheet h2{margin:0 0 24px}.sheet p{font-size:12px;color:#a2b797;line-height:1.8}.close{position:absolute;right:16px;top:12px;font-size:24px!important}.type-options{overflow:hidden;border-radius:14px}.type-options button{display:block;width:100%;background:#203125;min-height:52px;border-bottom:1px solid #ffffff08;text-transform:capitalize;font-size:14px}.preview{width:100%;max-height:65vh;object-fit:contain;border-radius:16px}.danger{color:#edb39f!important}.stickers{display:grid;grid-template-columns:repeat(4,1fr);gap:10px}.stickers img{width:100%;height:56px;object-fit:contain}.d5-sheet-enter-active,.d5-sheet-leave-active{transition:opacity .25s}.d5-sheet-enter-active .sheet,.d5-sheet-leave-active .sheet{transition:transform .25s}.d5-sheet-enter-from,.d5-sheet-leave-to{opacity:0}.d5-sheet-enter-from .sheet,.d5-sheet-leave-to .sheet{transform:translateY(80px)}.d5-page-enter-active,.d5-page-leave-active{transition:opacity .25s,transform .25s}.d5-page-enter-from,.d5-page-leave-to{opacity:0;transform:translateX(24px)}.d5-item-enter-active,.d5-item-leave-active{transition:opacity .25s,transform .25s}.d5-item-enter-from,.d5-item-leave-to{opacity:0;transform:translateY(14px)}
</style>
